def f(x):
    return -x**5 - 3*x**3 - 5*x + 3

def S(a):
    return f(a) + f(a-2) - 6

# test values
for a in [-1, 0, 0.5, 0.9, 1.0, 1.1, 1.5, 2, 3]:
    print(a, S(a))

# find root near 1
from scipy.optimize import brentq
print("root:", brentq(S, -5, 5))
"}

